plugins {
    id("zb.typescript-connector")
}

// api.yml is committed and regenerated by hand (`npm run generate:api`), never by the build.
// The unit tests read sample events that are git-ignored: fetch them first.
val fetchOcsfFixtures by tasks.registering(Exec::class) {
    description = "Fetches OCSF sample events (fixtures/generated/) from schema.ocsf.io"
    workingDir = projectDir
    commandLine("node", "scripts/generate.mjs", "--fixtures")
    inputs.file("scripts/generate.mjs")
    outputs.dir("fixtures/generated")
}
tasks.matching { it.name == "testUnitExec" }.configureEach { dependsOn(fetchOcsfFixtures) }

// Gate-stamp inputs: the default set (api.yml, src/, …) plus the generator.
project.extra["sourceDirs"] = listOf("src", "scripts")
